INSERT INTO public.testimonials (name, role_bn, role_en, quote_bn, quote_en, rating, sort_order, is_active) VALUES
('ফারহান কবির', 'ফাউন্ডার, StyleHub BD', 'Founder, StyleHub BD', 'ওয়েবসাইট আর Meta অ্যাডসের কম্বিনেশনে আমাদের সেল ৩ গুণ বেড়েছে। টিমের সাপোর্ট অসাধারণ।', 'With their website and Meta ads combo, our sales tripled. The team support is outstanding.', 5, 4, true),
('নুসরাত জাহান', 'সিইও, GlowKart', 'CEO, GlowKart', 'AI চ্যাটবট সেট আপ করার পর কাস্টমার রেসপন্স টাইম প্রায় শূন্যে নেমে এসেছে।', 'After setting up the AI chatbot, customer response time dropped to nearly zero.', 5, 5, true),
('মাহমুদুল হাসান', 'ওনার, TechZone', 'Owner, TechZone', 'Shopify স্টোর আর সার্ভার-সাইড ট্র্যাকিং সেটআপ একদম প্রফেশনাল ছিল। ROAS অনেক বেড়েছে।', 'The Shopify store and server-side tracking setup was super professional. ROAS jumped massively.', 5, 6, true),
('ইসরাত জাহান', 'ফাউন্ডার, Pure Bliss', 'Founder, Pure Bliss', 'প্যাকেজিং প্রোডাক্ট আর ব্র্যান্ডিং সলিউশন—সবকিছু এক জায়গায় পেয়ে অনেক সময় বেঁচেছে।', 'Packaging products and branding solutions all in one place saved us so much time.', 5, 7, true),
('আরিফুল ইসলাম', 'ডিরেক্টর, UrbanMart', 'Director, UrbanMart', 'অর্ডার ম্যানেজমেন্ট প্যানেল আমাদের অপারেশন ৫ গুণ দ্রুত করেছে। হাইলি রেকমেন্ডেড।', 'The order management panel made our operations 5x faster. Highly recommended.', 5, 8, true),
('সুমাইয়া রহমান', 'মার্কেটিং হেড, FashionFlow', 'Marketing Head, FashionFlow', 'SEO আর স্পিড অপ্টিমাইজেশনের পর গুগল র‍্যাংকিং অসাধারণ উন্নতি হয়েছে।', 'After SEO and speed optimization, our Google rankings improved dramatically.', 5, 9, true);
